args.command:
python - <<'PY'
import os
for root, dirs, files in os.walk('.'):
    dirs[:] = [d for d in dirs if d not in {'.git','node_modules'}]
    for f in files:
        p=os.path.join(root,f)
        try:
            s=open(p,errors='ignore').read()
        except: continue
        if any(x in s.lower() for x in ('cleanup','cron')):
            print('\n###',p)
            for i,line in enumerate(s.splitlines(),1):
                if any(x in line.lower() for x in ('cleanup','cron')):
                    print(f'{i}:{line}')
